INSTR = [
 ("INS-SICK-DAY-GENERAL","Sick day","","When ill with vomiting, diarrhea or poor intake: keep drinking fluids, check glucose every 3-4 hours, never stop basal insulin, and call your care team about stopping metformin or SGLT2 tablets (and GLP-1 injections if you have stomach symptoms) until you can eat and drink normally."),
 ("INS-KETONES","Sick day","SGLT2I|INSULIN_ANALOG","If glucose is above 200 mg/dL when unwell, check blood ketones. Go to hospital if you cannot keep fluids down, keep vomiting, ketones or sugars do not fall after insulin, or you feel confused or breathless."),
 ("INS-HYPO-TREAT","Safety","","Low sugar: take 15 g glucose (3-4 glucose tablets or about 150 mL juice), recheck in 15 minutes, repeat if still below 70 mg/dL, then eat a snack. Do not treat with chocolate or high-fat food first. If you take acarbose use pure glucose. Never give insulin to someone with a low."),
 ("INS-BP-HOME","Monitoring","","Check blood pressure at home sitting, after 5 minutes rest, arm at heart level; keep a log and bring it to visits. Usual goal is below 130/80 mmHg unless your doctor sets another goal."),
 ("INS-DASH","Nutrition","","Follow a DASH-style diet: more fruits, vegetables, low-fat dairy; less salt (below 2,300 mg sodium/day); limit alcohol; stay active."),
 ("INS-ACEI-ARB","Medication","ACEI_ARB","Do not take this medicine if pregnant or planning pregnancy; tell your doctor immediately. Report dizziness, fainting, swelling of lips/face. Blood tests for kidney function and potassium are needed; avoid potassium supplements and salt substitutes unless advised. Do not stop on your own."),
 ("INS-FINERENONE","Medication","NSMRA","Blood potassium will be checked about 1 month after starting and periodically. Avoid potassium supplements and potassium salt substitutes. Not for use in pregnancy."),
 ("INS-STATIN","Medication","STATIN","Take your statin daily. Report unexplained muscle pain, weakness or dark urine. A cholesterol test will be repeated 4-12 weeks after starting or changing the dose and then yearly. Not for use in pregnancy: tell your doctor if planning a baby."),
 ("INS-ASPIRIN","Medication","ASPIRIN","Take low-dose aspirin daily as prescribed with food. Report black stools, vomiting blood or unusual bleeding. Do not start or stop without advice."),
 ("INS-CKD-DIET","Nutrition","","With kidney disease: keep protein at about 0.8 g/kg body weight a day (not very low), limit salt, and follow your dietitian's advice about potassium. Avoid painkillers like ibuprofen or diclofenac."),
 ("INS-NSAID","Safety","","Avoid anti-inflammatory painkillers (ibuprofen, diclofenac, naproxen) because they can harm your kidneys; ask your pharmacist for safe alternatives."),
 ("INS-NEUROPATHIC-PAIN","Medication","NEUROPATHIC_PAIN","Nerve-pain medicines work gradually: start low and increase slowly. Tell your doctor about drowsiness, dizziness or stomach upset. Avoid opioid painkillers for nerve pain."),
 ("INS-FOOT-DAILY","Foot care","","Look at both feet every day (use an unbreakable mirror if needed) for cuts, blisters, redness, swelling or colour change. Wash and dry between toes, moisturize dry skin, never walk barefoot, and do not cut corns or calluses yourself. Report any wound at once."),
 ("INS-FOOTWEAR","Foot care","","Wear well-fitting shoes or prescribed therapeutic footwear/insoles; check inside shoes for stones before wearing."),
 ("INS-GLUCAGON-USE","Safety","GLUCAGON","Keep glucagon where family can find it, check the expiry date, and learn how to give it. After giving glucagon call emergency services."),
]

